  MIPStarRE.LDT.ProjStrat.PassesLowIndividualDegreeTest.{u_1, u_2, u_3} strategy eps →
    ∀ (k : ℕ),
      LE.le.{0} (HMul.hMul.{0, 0, 0} (HMul.hMul.{0, 0, 0} 400 params.m) params.d) k →
        have σ :=
          HMul.hMul.{0, 0, 0} 2
            (MIPStarRE.LDT.MainInductionStep.mainInductionError params k (HMul.hMul.{0, 0, 0} 3 eps)
              (HMul.hMul.{0, 0, 0} 3 eps) (HMul.hMul.{0, 0, 0} 3 eps));
        have ζ₁ :=
          HAdd.hAdd.{0, 0, 0}
