            (HDiv.hDiv.{0, 0, 0} (HMul.hMul.{0, 0, 0} ↑params.m ↑params.d) ↑params.q);
        have ζ₂ := MIPStarRE.LDT.MakingMeasurementsProjective.orthonormalizeAndCompleteError ζ₁;
        have η := HAdd.hAdd.{0, 0, 0} ζ₁ √(MIPStarRE.LDT.MakingMeasurementsProjective.orthonormalizationError ζ₁);
        have ζ₃ := HAdd.hAdd.{0, 0, 0} (HMul.hMul.{0, 0, 0} 6 ζ₁) (HMul.hMul.{0, 0, 0} 6 ζ₂);
        ∃ Q_A Q_B,
