                (MIPStarRE.LDT.uniformDistribution.{0} (MIPStarRE.LDT.Point params))
                (MIPStarRE.LDT.polynomialEvaluationFamily.{u_1, u_3} params
                  (MIPStarRE.LDT.Measurement.toSubMeas.{u_3, u_1}
                    (MIPStarRE.LDT.ProjMeas.toMeasurement.{u_3, u_1} Q_A)))
                (MIPStarRE.LDT.IdxProjMeas.toIdxSubMeas.{0, 0, u_2}
                  (MIPStarRE.LDT.ProjStrat.pointMeasurementB.{u_1, u_2, u_3} strategy))
                (HAdd.hAdd.{0, 0, 0} σ (HMul.hMul.{0, 0, 0} 2 √(HAdd.hAdd.{0, 0, 0} η (HDiv.hDiv.{0, 0, 0} ζ₃ 2)))) ∧
