                    (MIPStarRE.LDT.Measurement.toSubMeas.{u_3, u_1}
                      (MIPStarRE.LDT.ProjMeas.toMeasurement.{u_3, u_1} Q_A)))
                  (MIPStarRE.LDT.polynomialEvaluationFamily.{u_2, u_3} params
                    (MIPStarRE.LDT.Measurement.toSubMeas.{u_3, u_2}
                      (MIPStarRE.LDT.ProjMeas.toMeasurement.{u_3, u_2} Q_B)))
                  (HDiv.hDiv.{0, 0, 0} ζ₃ 2) ∧
                MIPStarRE.LDT.ConsRel.{0, u_3, u_1, u_2} (MIPStarRE.LDT.ProjStrat.state.{u_1, u_2, u_3} strategy)
                  (MIPStarRE.LDT.uniformDistribution.{0} Unit)
